insert into public.treks (slug, name, state, region, mountain_range, difficulty, duration_days, max_altitude_m, distance_km, best_months, seasons, base_camp, nearest_airport, nearest_railway, summary, description, highlights, tags, permits, cover_image_url, is_featured)
values
  ('kedarkantha', 'Kedarkantha', 'Uttarakhand', 'Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 6, 3810, 20, array['Dec', 'Jan', 'Feb', 'Mar', 'Apr']::text[], array['winter', 'spring']::text[], 'Sankri', 'Jolly Grant Airport, Dehradun', 'Dehradun', 'India''s most popular winter summit trek through snow-laden pine forests to a 360° Himalayan view.', 'Starting from the village of Sankri in Govind Wildlife Sanctuary, the Kedarkantha trail climbs through dense pine and oak forests to the frozen Juda ka Talab and a series of snowy campsites. The summit push begins before dawn and rewards trekkers with views of Swargarohini, Bandarpoonch and Black Peak.', array['Summit sunrise over Swargarohini', 'Juda ka Talab frozen lake', 'Snow camping in pine forests']::text[], array['himalayan', 'snow', 'summit', 'beginner', 'winter']::text[], 'Forest entry permit for Govind Wildlife Sanctuary (arranged at Sankri)', null, true),
  ('hampta-pass', 'Hampta Pass', 'Himachal Pradesh', 'Kullu–Lahaul', 'Pir Panjal', 'moderate'::public.trek_difficulty, 5, 4270, 26, array['Jun', 'Jul', 'Aug', 'Sep']::text[], array['summer', 'monsoon']::text[], 'Jobra', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A dramatic crossover from the green Kullu valley to the stark desert of Lahaul, with a side trip to Chandratal.', 'Hampta Pass connects the lush meadows of Kullu with the barren landscapes of Lahaul–Spiti. The trail follows river crossings, flower-filled meadows at Chika and Balu ka Ghera before the pass, and descends to Shea Goru. Most batches end with a drive to Chandratal lake.', array['Valley crossover from green to desert', 'Chandratal lake', 'River crossings']::text[], array['himalayan', 'pass', 'crossover', 'monsoon']::text[], 'Forest permit from Manali forest office', null, true),
  ('rajmachi', 'Rajmachi Fort', 'Maharashtra', 'Lonavala', 'Sahyadri (Western Ghats)', 'easy'::public.trek_difficulty, 1, 830, 15, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct']::text[], array['monsoon', 'autumn']::text[], 'Lonavala / Udhewadi', 'Pune Airport', 'Lonavala', 'A classic Sahyadri fort trek with twin citadels, waterfalls and fireflies in the pre-monsoon nights.', 'Rajmachi has two fortifications, Shrivardhan and Manaranjan, overlooking the Konkan and Ulhas valley. The wide jeep trail from Lonavala is gentle, making it ideal for first-timers, while the steeper Kondivade route from Karjat offers a tougher climb.', array['Twin forts Shrivardhan & Manaranjan', 'Monsoon waterfalls', 'Firefly festival in late May']::text[], array['sahyadri', 'fort', 'monsoon', 'beginner', 'weekend']::text[], null, null, false),
  ('valley-of-flowers', 'Valley of Flowers', 'Uttarakhand', 'Chamoli, Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 6, 3658, 38, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Govindghat', 'Jolly Grant Airport, Dehradun', 'Rishikesh / Haridwar', 'A UNESCO-listed alpine valley that erupts into carpets of wildflowers each monsoon.', 'The trail climbs from Govindghat to Ghangaria, from where the valley opens out as a wide glacial bowl dotted with hundreds of blooming species. Many itineraries add the steep climb to Hemkund Sahib. Rain is frequent, so the greenery peaks in late July and August.', array['Hundreds of alpine flower species', 'Pushpawati river valley', 'Optional climb to Hemkund Sahib', 'Misty monsoon meadows']::text[], array['himalayan', 'meadows', 'monsoon', 'family', 'cultural']::text[], 'Entry ticket for Nanda Devi Biosphere Reserve collected at Ghangaria; valley open roughly June to October', null, true),
  ('roopkund', 'Roopkund', 'Uttarakhand', 'Chamoli, Garhwal', 'Nanda Devi range', 'difficult'::public.trek_difficulty, 8, 5029, 53, array['May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Lohajung', 'Jolly Grant Airport, Dehradun', 'Kathgodam / Haridwar', 'The famed ''skeleton lake'' trek through bugyals to a glacial tarn at over 5,000 m.', 'Starting at Lohajung, the route passes Ali and Bedni Bugyals, two of the largest high-altitude meadows in the Himalaya, before the climb to Bhagwabasa. The final push to the tarn crosses snow and loose scree, with Trishul and Nanda Ghunti dominating the skyline. Camping rules in the meadows have changed over the years, so check current guidelines.', array['Ali and Bedni Bugyals', 'Skeleton-lake legend', 'Views of Trishul and Nanda Ghunti', 'Snow trek to Junargali ridge']::text[], array['himalayan', 'meadows', 'snow', 'high-altitude', 'camping', 'lakes']::text[], null, null, true),
  ('har-ki-dun', 'Har Ki Dun', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 7, 3566, 47, array['Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'Sankri', 'Jolly Grant Airport, Dehradun', 'Dehradun', 'A pastoral hanging valley trek through ancient villages, with snow peaks at its head.', 'The route follows the Tons tributary from Taluka through the villages of Osla and Gangad, where wooden temples and terraced fields set the pace. Higher up, the valley widens into meadows beneath Swargarohini and Bandarpoonch. It is a rewarding year-round option, with snow in winter and flowers in early summer.', array['Osla village and its Duryodhana temple', 'Swargarohini peaks', 'Alpine meadows and river camps', 'Option to continue to Ruinsara Tal']::text[], array['himalayan', 'meadows', 'river', 'forest', 'cultural', 'camping']::text[], null, null, true),
  ('brahmatal', 'Brahmatal', 'Uttarakhand', 'Chamoli, Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 6, 3734, 24, array['Dec', 'Jan', 'Feb', 'Mar']::text[], array['winter', 'spring']::text[], 'Lohajung', 'Jolly Grant Airport, Dehradun', 'Kathgodam', 'A snowy winter walk to a frozen lake with front-row views of Trishul and Nanda Ghunti.', 'Beginning from Lohajung, the trail climbs through oak and rhododendron forest to Bekaltal and then the ridge above Brahmatal. The camp at Jhandi Top gives a sweeping view across the Garhwal and Kumaon ranges. It is a popular alternative to Kedarkantha for a first snow trek.', array['Frozen Bekaltal and Brahmatal lakes', 'Jhandi Top panorama', 'Snow-laden oak forest', 'Mt Trishul views']::text[], array['himalayan', 'snow', 'lakes', 'forest', 'winter', 'beginner']::text[], null, null, true),
  ('kuari-pass', 'Kuari Pass', 'Uttarakhand', 'Chamoli, Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 5, 3815, 33, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'Joshimath', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'The ''Curzon Trail'' ridge walk with an unbroken line of Himalayan giants.', 'This ridge trek from Joshimath crosses Gorson Bugyal and Tali before reaching the pass. Nanda Devi, Dronagiri, Kamet and Hathi Parvat line up across the horizon on clear days. It works well in winter snow and again in spring.', array['Nanda Devi and Dronagiri views', 'Gorson Bugyal', 'Historic Curzon Trail', 'Oak and rhododendron woods']::text[], array['himalayan', 'pass', 'snow', 'meadows', 'forest', 'winter']::text[], null, null, false),
  ('pangarchulla', 'Pangarchulla Peak', 'Uttarakhand', 'Chamoli, Garhwal', 'Garhwal Himalaya', 'difficult'::public.trek_difficulty, 6, 4590, 29, array['Mar', 'Apr', 'May', 'Nov', 'Dec']::text[], array['spring', 'autumn', 'winter']::text[], 'Joshimath', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'A steep summit climb from Tali that combines winter snow with bold Himalayan panoramas.', 'Following the Kuari Pass trail, the route diverges at Khullara and gains height quickly over snow and rock to the summit ridge. The last stretch requires sure footing and an early start. The top gives views of Dronagiri, Nanda Devi and Chaukhamba.', array['Summit with 360° Himalayan views', 'Snow camping at Khullara', 'Combines meadows and ridge walking']::text[], array['himalayan', 'summit', 'snow', 'high-altitude', 'winter']::text[], null, null, false),
  ('dayara-bugyal', 'Dayara Bugyal', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'easy'::public.trek_difficulty, 4, 3408, 22, array['Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'Barsu', 'Jolly Grant Airport, Dehradun', 'Dehradun / Rishikesh', 'One of Garhwal''s most spacious meadows, ideal for a first Himalayan trek.', 'The gentle path from Barsu village climbs through forest to Barnala Lake and then into the sweeping bugyal. In winter the entire meadow turns into a ski-slope-like snowfield. Views include Bandarpoonch, Draupadi ka Danda and Srikanth.', array['Wide ski-slope meadows', 'Barnala Tal', 'Bandarpoonch views', 'Easy gradients']::text[], array['himalayan', 'meadows', 'snow', 'beginner', 'family', 'winter']::text[], null, null, false),
  ('chopta-tungnath-chandrashila', 'Chopta Tungnath Chandrashila', 'Uttarakhand', 'Rudraprayag, Garhwal', 'Garhwal Himalaya', 'easy'::public.trek_difficulty, 3, 4000, 12, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'Chopta', 'Jolly Grant Airport, Dehradun', 'Haridwar / Rishikesh', 'A short temple-and-summit trek that reaches the world''s highest Shiva temple and a classic peak.', 'From Chopta the stone-paved trail climbs through rhododendron forest to Tungnath, the highest of the Panch Kedar temples. A further steep stretch leads to Chandrashila summit. Sunrise from the top lights up Nanda Devi, Trishul, Chaukhamba and Kedarnath peaks.', array['Tungnath temple', 'Chandrashila summit sunrise', 'Rhododendron bloom in spring', 'Chopta meadows']::text[], array['himalayan', 'summit', 'forest', 'cultural', 'beginner', 'weekend']::text[], null, null, false),
  ('kedartal', 'Kedartal', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Gangotri Himalaya', 'difficult'::public.trek_difficulty, 6, 4750, 34, array['May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Gangotri', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'A rugged glacial-lake trek from Gangotri below the Thalay Sagar peak.', 'The route follows the Kedar Ganga up a steep gorge past Bhoj Kharak and Kedar Kharak to the emerald lake. Boulder fields and steep rocky patches make the approach demanding. Thalay Sagar and Bhrigupanth tower overhead.', array['Emerald glacial lake', 'Thalay Sagar views', 'Gangotri river gorge']::text[], array['himalayan', 'lakes', 'glacier', 'high-altitude', 'river', 'camping']::text[], 'Gangotri National Park entry permit from Uttarkashi forest office', null, false),
  ('bali-pass', 'Bali Pass', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'challenging'::public.trek_difficulty, 8, 4950, 60, array['Jun', 'Sep', 'Oct']::text[], array['summer', 'monsoon', 'autumn']::text[], 'Sankri', 'Jolly Grant Airport, Dehradun', 'Dehradun', 'A demanding crossover from the Tons valley to Yamunotri via Ruinsara Tal.', 'The trail runs past Taluka and Osla to Ruinsara Tal, then crosses steep scree and glacier terrain over Bali Pass into the Yamunotri side. Weather windows are narrow and navigation requires an experienced guide. It is among the most rewarding crossovers in the region.', array['Ruinsara Tal', 'Glacier and boulder crossing', 'Descent to Yamunotri']::text[], array['himalayan', 'pass', 'crossover', 'high-altitude', 'lakes', 'camping']::text[], null, null, false),
  ('kalindi-khal', 'Kalindi Khal', 'Uttarakhand', 'Uttarkashi / Chamoli, Garhwal', 'Garhwal Himalaya', 'challenging'::public.trek_difficulty, 10, 5950, 100, array['Sep']::text[], array['monsoon']::text[], 'Gangotri', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'An expedition-grade glacier crossing from Gangotri to Badrinath beneath Chaukhamba.', 'The route follows Gaumukh and Tapovan, then traverses crevassed glaciers to reach the high col. A descent through the Arwa valley leads to Mana and Badrinath. It needs technical skills, acclimatisation and a strong support team.', array['Glacier traverse', 'Tapovan and Nandanvan', 'Chaukhamba and Kamet views']::text[], array['himalayan', 'pass', 'crossover', 'glacier', 'high-altitude', 'camping']::text[], 'Permits are generally arranged by the expedition operator; confirm current requirements', null, false),
  ('rupin-pass', 'Rupin Pass', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'difficult'::public.trek_difficulty, 8, 4650, 52, array['May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Dhaula', 'Jolly Grant Airport, Dehradun', 'Dehradun', 'A crossover from Uttarakhand to Himachal famed for its three-tiered frozen waterfall.', 'The trail starts in Dhaula and rises beside the Rupin river through villages, forest and meadows to the base of an immense three-stage waterfall. Snow slopes lead up to the pass, followed by a long descent to Sangla in Himachal. It rewards trekkers with unusually varied terrain.', array['Three-stage Rupin waterfall', 'Village-to-snowfield variety', 'Crossover into Sangla valley']::text[], array['himalayan', 'pass', 'crossover', 'waterfall', 'snow', 'river', 'camping']::text[], null, null, false),
  ('borasu-pass', 'Borasu Pass', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'challenging'::public.trek_difficulty, 8, 5450, 60, array['Jun', 'Sep', 'Oct']::text[], array['summer', 'monsoon', 'autumn']::text[], 'Harsil', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'A high crossover from Harsil to Chitkul in Himachal, passing Kinnaur Kailash views.', 'The route climbs from Harsil through remote meadows and moraines to the pass. Descent leads to Chitkul, one of the last villages before the Tibet border. Snow and thin air make this a seasoned trekker''s route.', array['Remote high pasture', 'Descent into Chitkul', 'Glacial terrain']::text[], array['himalayan', 'pass', 'crossover', 'high-altitude', 'camping']::text[], null, null, false),
  ('nag-tibba', 'Nag Tibba', 'Uttarakhand', 'Tehri Garhwal', 'Lesser Himalaya', 'easy'::public.trek_difficulty, 2, 3022, 10, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['autumn', 'winter', 'spring']::text[], 'Pantwari', 'Jolly Grant Airport, Dehradun', 'Dehradun', 'A quick weekend getaway from Dehradun and Delhi with big Himalayan views.', 'Starting at Pantwari, the trail winds through oak and deodar forest to a camp near the Nag Devta temple. The summit gives a line-up of Bandarpoonch, Kedarnath, Swargarohini and Gangotri peaks. Snow lines the route after winter storms.', array['Weekend-friendly distance', 'Nag Devta temple', 'Snowy winter trail']::text[], array['himalayan', 'summit', 'snow', 'weekend', 'beginner', 'winter']::text[], null, null, false),
  ('phulara-ridge', 'Phulara Ridge', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 6, 3500, 30, array['Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Sankri', 'Jolly Grant Airport, Dehradun', 'Dehradun', 'A ridge-top trek with long meadow walks and close views of Bandarpoonch and Black Peak.', 'The trail starts near Sankri, rises through oak woods, then follows a long ridge that opens onto dramatic meadows. Camps along the ridge give wide sunrise and sunset views. The terrain is moderate with little rocky scrambling.', array['Ridge-top camps', 'Bandarpoonch panorama', 'Lush meadows']::text[], array['himalayan', 'meadows', 'forest', 'camping']::text[], null, null, false),
  ('satopanth-lake', 'Satopanth Lake', 'Uttarakhand', 'Chamoli, Garhwal', 'Garhwal Himalaya', 'difficult'::public.trek_difficulty, 7, 4600, 50, array['Jun', 'Sep', 'Oct']::text[], array['summer', 'monsoon', 'autumn']::text[], 'Mana', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'A sacred glacial lake trek beyond Mana village with Neelkanth rising overhead.', 'The route leaves Badrinath for Mana, crosses the Saraswati, and follows the Alaknanda glacier valley to Satopanth Tal and the Vasudhara fall. Boulder hopping and cold winds define the high stretch. The triangular lake is revered by pilgrims.', array['Vasudhara waterfall', 'Sacred triangular lake', 'Neelkanth views']::text[], array['himalayan', 'lakes', 'glacier', 'cultural', 'high-altitude']::text[], null, null, false),
  ('pindari-glacier', 'Pindari Glacier', 'Uttarakhand', 'Bageshwar, Kumaon', 'Kumaon Himalaya', 'moderate'::public.trek_difficulty, 6, 3627, 94, array['Apr', 'May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Loharkhet', 'Pantnagar Airport', 'Kathgodam', 'A classic Kumaon trek along the Pindar river to the glacier snout.', 'From Loharkhet the trail passes villages, deodar and rhododendron forests, then climbs to Dwali, Phurkia and Zero Point. The valley opens to Nanda Kot and Panwali Dwar. The long approach is gradual and rewarding.', array['Glacier snout at Zero Point', 'Pindar river valley', 'Kumaoni villages', 'Nanda Kot views']::text[], array['himalayan', 'glacier', 'river', 'forest', 'camping']::text[], null, null, false),
  ('kafni-glacier', 'Kafni Glacier', 'Uttarakhand', 'Bageshwar, Kumaon', 'Kumaon Himalaya', 'moderate'::public.trek_difficulty, 6, 3860, 60, array['Apr', 'May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Song', 'Pantnagar Airport', 'Kathgodam', 'A quieter Kumaon glacier trek beside the Pindari route, ending beneath Nanda Kot.', 'The trail climbs from Song through Khati village and Dwali to Kafni glacier, a side branch of the same valley as Pindari. Villages, forest and crashing streams punctuate the walk. Many trekkers combine it with Pindari.', array['Kafni glacier snout', 'Quiet river valleys', 'Khati village']::text[], array['himalayan', 'glacier', 'river', 'forest', 'camping']::text[], null, null, false),
  ('audens-col', 'Auden''s Col', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'challenging'::public.trek_difficulty, 12, 5490, 70, array['Sep']::text[], array['monsoon']::text[], 'Gangotri', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'A technical glacier crossing from Bhilangna valley to Gangotri.', 'This route climbs through Kharsoli and Khatling glacier, then traverses crevasses and snow slopes to the col. Rope work, crampons and stable weather are essential. Only experienced high-altitude trekkers should attempt it.', array['Glacier traverse', 'Crevasse crossing', 'Jogin and Thalay Sagar views']::text[], array['himalayan', 'pass', 'crossover', 'glacier', 'high-altitude']::text[], null, null, false),
  ('gaumukh-tapovan', 'Gaumukh Tapovan', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Gangotri Himalaya', 'difficult'::public.trek_difficulty, 6, 4463, 44, array['May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Gangotri', 'Jolly Grant Airport, Dehradun', 'Rishikesh', 'A pilgrimage trek to the Ganges source and the high meadow of Tapovan beneath Shivling.', 'The trail leaves Gangotri for Chirbasa and Bhojbasa, then reaches the Gaumukh snout. A steep boulder climb leads to Tapovan, where Shivling dominates the horizon. Daily permits are limited, so plan ahead.', array['Gaumukh glacier snout', 'Shivling views at Tapovan', 'Bhagirathi sisters']::text[], array['himalayan', 'glacier', 'cultural', 'high-altitude', 'meadows', 'camping']::text[], 'Gangotri National Park entry permit required (daily limits apply)', null, false),
  ('hemkund-sahib', 'Hemkund Sahib', 'Uttarakhand', 'Chamoli, Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 2, 4329, 21, array['Jun', 'Jul', 'Aug', 'Sep']::text[], array['summer', 'monsoon']::text[], 'Govindghat', 'Jolly Grant Airport, Dehradun', 'Rishikesh / Haridwar', 'A steep pilgrimage climb to a glacial lake and Sikh shrine.', 'From Ghangaria the paved path zigzags up to the gurdwara beside the lake. The altitude makes the climb tiring despite the short distance. Most visitors combine it with the Valley of Flowers.', array['Glacial lake and gurdwara', 'Alpine flora', 'Pilgrim route']::text[], array['himalayan', 'cultural', 'lakes', 'family']::text[], null, null, false),
  ('deoria-tal', 'Deoria Tal', 'Uttarakhand', 'Rudraprayag, Garhwal', 'Garhwal Himalaya', 'easy'::public.trek_difficulty, 2, 2438, 6, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'Sari', 'Jolly Grant Airport, Dehradun', 'Haridwar / Rishikesh', 'A short walk to a mirror-like lake reflecting the Chaukhamba range.', 'The easy trail climbs through oak and rhododendron forest from Sari village. The lake reflects Chaukhamba, Neelkanth and Kedarnath peaks, especially at sunrise. It is a popular add-on to Chopta.', array['Chaukhamba reflections', 'Rhododendron forest', 'Sari village']::text[], array['himalayan', 'lakes', 'beginner', 'weekend', 'family']::text[], null, null, false),
  ('ali-bedni-bugyal', 'Ali Bedni Bugyal', 'Uttarakhand', 'Chamoli, Garhwal', 'Nanda Devi range', 'moderate'::public.trek_difficulty, 5, 3354, 34, array['Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Lohajung', 'Jolly Grant Airport, Dehradun', 'Kathgodam', 'A meadow trek through Asia''s largest high-altitude grasslands.', 'The trail climbs from Lohajung through Wan village and oak forest to Bedni Bugyal, with its tiny lake. Ali Bugyal stretches above for a vast panorama of Trishul and Nanda Ghunti. Camping rules at the meadows have been revised, so check current guidelines.', array['Huge open meadows', 'Bedni Kund', 'Trishul and Nanda Ghunti']::text[], array['himalayan', 'meadows', 'lakes', 'forest', 'camping']::text[], null, null, false),
  ('dodital-darwa-pass', 'Dodital Darwa Pass', 'Uttarakhand', 'Uttarkashi, Garhwal', 'Garhwal Himalaya', 'moderate'::public.trek_difficulty, 5, 4150, 40, array['Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Sangamchatti', 'Jolly Grant Airport, Dehradun', 'Dehradun', 'A trek to Ganesha''s reputed birthplace lake and over the Darwa Pass.', 'The route climbs from Sangamchatti through dense forest and the Agoda village to Dodital. Beyond the lake, it crosses Darwa Top and descends to Hanuman Chatti. Rainbow trout swim in the lake.', array['Dodital lake', 'Darwa Pass', 'Dense deodar forest']::text[], array['himalayan', 'lakes', 'pass', 'forest', 'camping']::text[], null, null, false),
  ('triund', 'Triund', 'Himachal Pradesh', 'Kangra', 'Dhauladhar range', 'easy'::public.trek_difficulty, 2, 2828, 18, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'McLeod Ganj', 'Gaggal Airport, Kangra', 'Pathankot', 'A beloved short ridge walk above McLeod Ganj facing the Dhauladhar wall.', 'The trail climbs from Dharamkot through oak and rhododendron to a grassy ridge at the foot of the Dhauladhar. Night stays on the ridge bring starry skies and sunrise over the Kangra valley. It is ideal for first-timers and weekend breaks.', array['Dhauladhar views', 'Ridge camping', 'Kangra valley sunrise']::text[], array['himalayan', 'beginner', 'weekend', 'camping', 'family']::text[], null, null, false),
  ('beas-kund', 'Beas Kund', 'Himachal Pradesh', 'Kullu', 'Pir Panjal', 'moderate'::public.trek_difficulty, 4, 3700, 16, array['May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Solang Nala', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A glacial-lake trek near Manali at the source of the Beas river.', 'From Solang the route climbs through Dhundi, Bakarthach and the lake itself, ringed by Hanuman Tibba, Ladakhi and Shitidhar peaks. Spring brings snowfields and summer flower meadows. It is a popular short trek from Manali.', array['Beas source lake', 'Hanuman Tibba views', 'Flower meadows']::text[], array['himalayan', 'lakes', 'snow', 'meadows', 'camping']::text[], null, null, false),
  ('bhrigu-lake', 'Bhrigu Lake', 'Himachal Pradesh', 'Kullu', 'Pir Panjal', 'moderate'::public.trek_difficulty, 4, 4300, 23, array['May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Gulaba', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A high-altitude lake near Rohtang that stays semi-frozen into summer.', 'The trail starts at Gulaba, passes Rola Kholi and climbs over grassy ridges to the lake. Views extend to Pir Panjal and Lahaul peaks. Weather changes fast, so an early start is key.', array['Semi-frozen alpine lake', 'Rola Kholi meadows', 'Views over Manali']::text[], array['himalayan', 'lakes', 'meadows', 'snow', 'camping']::text[], null, null, false),
  ('pin-parvati-pass', 'Pin Parvati Pass', 'Himachal Pradesh', 'Kullu–Spiti', 'Pir Panjal', 'challenging'::public.trek_difficulty, 11, 5319, 110, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Barshaini', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A long crossover from the Parvati valley''s hot springs to Spiti''s cold desert.', 'The route follows the Parvati river through Mantalai and Thakur Kuan, then climbs boulders and glacier moraines to the pass. Descent leads through Pin valley to Mud village. It demands stamina, stream crossings and high-altitude experience.', array['Mantalai lake', 'Glacier-boulder crossing', 'Parvati-to-Spiti crossover']::text[], array['himalayan', 'pass', 'crossover', 'glacier', 'high-altitude', 'camping']::text[], null, null, false),
  ('kheerganga', 'Kheerganga', 'Himachal Pradesh', 'Kullu', 'Parvati valley', 'easy'::public.trek_difficulty, 2, 2960, 12, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Barshaini', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A lively Parvati valley hike to hot springs in a meadow.', 'The trail starts in Barshaini, passes Nakthan village and runs beside waterfalls and pine forest to a meadow with a natural hot spring. Many hikers camp overnight. It is accessible in most seasons except heavy snow.', array['Natural hot spring', 'Waterfall trail', 'Meadow camping']::text[], array['himalayan', 'beginner', 'weekend', 'camping', 'waterfall']::text[], null, null, false),
  ('prashar-lake', 'Prashar Lake', 'Himachal Pradesh', 'Mandi', 'Dhauladhar range', 'easy'::public.trek_difficulty, 2, 2730, 8, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'Baggi', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A floating-island lake beside a pagoda-style temple, ringed by deodar forest.', 'The trail rises from Baggi through oak and cedar to a wide meadow with the lake and ancient Prashar Rishi temple. The central floating island drifts over the water. Peaks of the Pir Panjal and Dhauladhar appear on clear days.', array['Floating island', 'Pagoda temple', 'Panoramic ridge views']::text[], array['himalayan', 'lakes', 'cultural', 'beginner', 'weekend']::text[], null, null, false),
  ('sar-pass', 'Sar Pass', 'Himachal Pradesh', 'Kullu', 'Parvati valley', 'moderate'::public.trek_difficulty, 6, 4220, 48, array['May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Kasol', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A snow-slide pass trek starting from the Parvati valley''s backpacker village.', 'From Grahan, the route climbs through Min Thach and Nagaru into snowfields and a steep slide to Biskeri Thach. The pass gives wide views of the Parvati valley. Snow is present for much of the season.', array['Snow slide descent', 'Grahan village', 'Alpine ridge']::text[], array['himalayan', 'pass', 'snow', 'camping', 'meadows']::text[], null, null, false),
  ('indrahar-pass', 'Indrahar Pass', 'Himachal Pradesh', 'Kangra', 'Dhauladhar range', 'difficult'::public.trek_difficulty, 4, 4342, 35, array['May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'McLeod Ganj', 'Gaggal Airport, Kangra', 'Pathankot', 'A steep Dhauladhar crossover over Triund and Lahesh cave.', 'The route continues from Triund over snowfields and rocky ridges to Laka Got and Lahesh Cave. The final rocky climb leads to a narrow pass with views over Chamba and Kangra. Snow and thin air make it demanding.', array['Crossover to Chamba', 'Lahesh Cave', 'High ridge']::text[], array['himalayan', 'pass', 'snow', 'high-altitude', 'camping']::text[], null, null, false),
  ('buran-ghati', 'Buran Ghati', 'Himachal Pradesh', 'Shimla', 'Pir Panjal', 'difficult'::public.trek_difficulty, 6, 4572, 40, array['May', 'Jun', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Janglik', 'Jubbarhatti Airport, Shimla', 'Kalka / Shimla', 'A snow pass trek from Janglik to Dodra Kwar with sweeping shepherd meadows.', 'The path climbs through Dayara Thach and Litham, with sprawling grass bowls enclosing the route. The pass itself rises over steep snow and glacial moraines. A long descent finishes in remote villages.', array['Shepherd meadows', 'Snow pass crossing', 'Remote villages']::text[], array['himalayan', 'pass', 'snow', 'meadows', 'camping']::text[], null, null, false),
  ('chandrakhani-pass', 'Chandrakhani Pass', 'Himachal Pradesh', 'Kullu', 'Pir Panjal', 'moderate'::public.trek_difficulty, 4, 3660, 16, array['May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Naggar', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A culture-rich pass trek from Naggar to the ancient village of Malana.', 'The trail climbs through Rumsu and Chandrakhani Top, with views of Deo Tibba and the Parvati range. It then descends through pine forest to Malana. The area has unique local customs, so respectful behaviour is essential.', array['Malana village', 'Chandrakhani Top', 'Deo Tibba views']::text[], array['himalayan', 'pass', 'cultural', 'forest']::text[], null, null, false),
  ('kareri-lake', 'Kareri Lake', 'Himachal Pradesh', 'Kangra', 'Dhauladhar range', 'easy'::public.trek_difficulty, 3, 2934, 28, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Ghera', 'Gaggal Airport, Kangra', 'Pathankot', 'A pleasant forest and stream trek to a lake beneath the Dhauladhar.', 'From Ghera village the trail follows the Nyund stream through woods and waterfalls to Kareri Lake. Stream crossings can be tricky after rain. Views of Minvakhi peak enhance the camp.', array['Forest stream trail', 'High lake', 'Dhauladhar views']::text[], array['himalayan', 'lakes', 'forest', 'beginner', 'camping']::text[], null, null, false),
  ('pin-bhaba-pass', 'Pin Bhaba Pass', 'Himachal Pradesh', 'Kinnaur–Spiti', 'Himalaya', 'difficult'::public.trek_difficulty, 8, 4850, 60, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Kafnu', 'Jubbarhatti Airport, Shimla', 'Shimla / Kalka', 'A dramatic crossover from the green Bhaba valley to the arid Pin valley.', 'The route climbs along the Bhaba river through alpine forest to Mulling and Phustirang meadows, then over a rocky pass. The contrast between Kinnaur''s greenery and Spiti''s desert is stark. Monsoon rain can affect the lower trail.', array['Green-to-desert contrast', 'Bhaba valley', 'Pin valley']::text[], array['himalayan', 'pass', 'crossover', 'meadows', 'camping']::text[], null, null, false),
  ('kinner-kailash', 'Kinner Kailash', 'Himachal Pradesh', 'Kinnaur', 'Kinnaur Kailash range', 'difficult'::public.trek_difficulty, 3, 5242, 28, array['Aug', 'Sep']::text[], array['monsoon']::text[], 'Kalpa', 'Jubbarhatti Airport, Shimla', 'Shimla / Kalka', 'A steep pilgrim trek to a 79-foot rock formation revered as a Shiva linga.', 'The climb begins near Powari and ascends via Ganesh Park and Parvati Kund. The air is thin and the terrain unforgiving, making it a serious one-day push. The reward is a sacred natural shrine.', array['Natural Shiva linga rock', 'Kinnaur panorama', 'Parvati Kund']::text[], array['himalayan', 'cultural', 'high-altitude', 'pass']::text[], null, null, false),
  ('jalori-serolsar', 'Serolsar Lake via Jalori Pass', 'Himachal Pradesh', 'Kullu', 'Pir Panjal', 'easy'::public.trek_difficulty, 2, 3100, 10, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Jibhi', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A gentle forest trail to a sacred lake near the Jalori Pass.', 'The path climbs from Jalori Pass through oak and spruce, with a small temple at the lake. Mist often shrouds the forest. The lake is a favourite among beginners.', array['Sacred lake', 'Spruce forest', 'Jibhi valley']::text[], array['himalayan', 'lakes', 'forest', 'beginner', 'weekend']::text[], null, null, false),
  ('churdhar', 'Churdhar', 'Himachal Pradesh', 'Sirmaur', 'Shivalik–Lesser Himalaya', 'moderate'::public.trek_difficulty, 2, 3647, 16, array['Mar', 'Apr', 'May', 'Jun', 'Sep', 'Oct', 'Nov', 'Dec']::text[], array['spring', 'summer', 'monsoon', 'autumn', 'winter']::text[], 'Nohradhar', 'Jubbarhatti Airport, Shimla', 'Ambala / Kalka', 'The highest peak in the Sirmaur region, with a huge viewing platform.', 'The trail climbs from Nohradhar through deodar and oak forest to the summit temple. From the top, views span the Shivaliks to the snow peaks. It is a rewarding two-day trek close to Chandigarh and Shimla.', array['Summit temple', 'Deodar forests', 'Sunrise over Shivaliks']::text[], array['himalayan', 'summit', 'forest', 'cultural', 'weekend']::text[], null, null, false),
  ('shrikhand-mahadev', 'Shrikhand Mahadev', 'Himachal Pradesh', 'Kullu', 'Great Himalaya', 'difficult'::public.trek_difficulty, 5, 5227, 35, array['Jul']::text[], array['monsoon']::text[], 'Jaon', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A stiff pilgrimage to a 72-foot Shiva linga, usually walked during the annual yatra.', 'The route climbs through Singhgad, Thachru and Bheem Dwar before the steep final stretch. Narrow trails, snow and exposed sections require care. The pilgrimage is held for a short period each July.', array['Annual pilgrimage', 'Alpine meadows', 'Views of Great Himalaya']::text[], array['himalayan', 'cultural', 'high-altitude', 'camping']::text[], null, null, false),
  ('chandratal-batal', 'Chandratal Lake via Batal', 'Himachal Pradesh', 'Lahaul and Spiti', 'Lahaul Himalaya', 'easy'::public.trek_difficulty, 2, 4300, 14, array['Jun', 'Jul', 'Aug', 'Sep']::text[], array['summer', 'monsoon']::text[], 'Batal', 'Bhuntar Airport, Kullu', 'Joginder Nagar', 'A short walk from Batal to a moon-shaped lake in Lahaul.', 'The trail follows the Chandra river valley before opening onto the high-altitude lake. Camping beside the lake is a highlight, though it requires care to leave no trace. Roads to Batal close in winter.', array['Crescent-shaped lake', 'High desert scenery', 'Easy gradients']::text[], array['himalayan', 'lakes', 'camping', 'family']::text[], null, null, false),
  ('kashmir-great-lakes', 'Kashmir Great Lakes', 'Jammu and Kashmir', 'Sonamarg, Kashmir', 'Pir Panjal and Great Himalaya', 'moderate'::public.trek_difficulty, 7, 4200, 70, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Sonamarg', 'Srinagar Airport', 'Srinagar / Jammu Tawi', 'A signature Kashmir trek linking alpine lakes beneath glaciated peaks.', 'The trail crosses Nichnai and Gadsar passes, with lakes including Vishansar, Kishansar, Gadsar and Satsar. Meadows are flower-strewn in summer. Weather can turn quickly, so layers and rain gear matter.', array['Vishansar, Kishansar and Gadsar lakes', 'Flower-filled meadows', 'Gadsar Pass']::text[], array['himalayan', 'lakes', 'pass', 'meadows', 'high-altitude', 'camping']::text[], null, null, true),
  ('tarsar-marsar', 'Tarsar Marsar', 'Jammu and Kashmir', 'Pahalgam, Kashmir', 'Pir Panjal', 'moderate'::public.trek_difficulty, 6, 3900, 50, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Aru', 'Srinagar Airport', 'Srinagar / Jammu Tawi', 'A twin-lake trek from Aru through pastoral Kashmir valleys.', 'From Aru the trail passes Lidderwat and Shekwas into the Tarsar basin, then over the Sumbal pass to Marsar. Green hills and shepherd huts line the route. It is an alternative to the Great Lakes for those wanting fewer crowds.', array['Twin lakes', 'Shekwas meadows', 'Sumbal pass']::text[], array['himalayan', 'lakes', 'meadows', 'camping']::text[], null, null, false),
  ('gangabal-nundkol', 'Gangabal and Nundkol', 'Jammu and Kashmir', 'Ganderbal, Kashmir', 'Great Himalaya', 'moderate'::public.trek_difficulty, 5, 3658, 40, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Naranag', 'Srinagar Airport', 'Srinagar / Jammu Tawi', 'A two-lake trek beneath Mt Harmukh with alpine views.', 'From Naranag the route climbs through forest and meadows to Gangabal Lake, then Nundkol beyond. Mt Harmukh rises above the shore. Lake-side camps make for striking sunrises.', array['Lake at the foot of Harmukh', 'Nundkol lake', 'Wildflower meadows']::text[], array['himalayan', 'lakes', 'meadows', 'camping']::text[], null, null, false),
  ('kolahoi-glacier', 'Kolahoi Glacier', 'Jammu and Kashmir', 'Pahalgam, Kashmir', 'Pir Panjal', 'moderate'::public.trek_difficulty, 4, 3600, 33, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Aru', 'Srinagar Airport', 'Srinagar / Jammu Tawi', 'A forest-to-glacier trek in Lidder valley toward the Matterhorn of Kashmir.', 'The path runs from Aru along the Lidder river through Lidderwat to the glacier. Tall Kolahoi peak looms over the final stretch. Boulder stretches are slippery after rain.', array['Kolahoi peak views', 'Lidder river valley', 'Glacier approach']::text[], array['himalayan', 'glacier', 'river', 'camping']::text[], null, null, false),
  ('warwan-valley', 'Warwan Valley', 'Jammu and Kashmir', 'Kishtwar, Jammu', 'Great Himalaya', 'moderate'::public.trek_difficulty, 8, 4418, 80, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Inshan', 'Srinagar Airport', 'Jammu Tawi', 'A remote valley crossing from Kishtwar to Anantnag via Margan Top.', 'This lesser-visited route follows the Marwah and Warwan river valleys through isolated settlements. It then climbs Margan Top to descend into Kashmir. Logistics are demanding, so go with a local outfit.', array['Remote villages', 'Margan Top crossing', 'Quiet river valley']::text[], array['himalayan', 'crossover', 'river', 'camping', 'cultural']::text[], 'Access to some Kashmir treks has been temporarily suspended at times; confirm with your organizer before planning.', null, false),
  ('chadar', 'Chadar Trek', 'Ladakh', 'Zanskar', 'Zanskar range', 'difficult'::public.trek_difficulty, 9, 3400, 105, array['Jan', 'Feb']::text[], array['winter']::text[], 'Chilling', 'Kushok Bakula Rimpochee Airport, Leh', 'Jammu Tawi', 'A winter walk on the frozen Zanskar river, with ice and cold canyons.', 'Trekkers walk on the ice of the Zanskar river for about 100 km, camping in caves and tents beside the gorge. Temperatures can plunge below -20 C. Ice and access conditions vary, so confirm current status before booking.', array['Frozen river walking', 'Nerak waterfall', 'Ice caves']::text[], array['himalayan', 'river', 'winter', 'snow', 'camping', 'high-altitude']::text[], null, null, false),
  ('markha-valley', 'Markha Valley', 'Ladakh', 'Leh', 'Zanskar range', 'moderate'::public.trek_difficulty, 8, 5260, 80, array['Jun', 'Jul', 'Aug', 'Sep']::text[], array['summer', 'monsoon']::text[], 'Chilling', 'Kushok Bakula Rimpochee Airport, Leh', 'Jammu Tawi', 'A Ladakh classic crossing stark valleys, villages and the Kongmaru La pass.', 'The trek follows the Markha river through Hemis National Park, with homestay and camp options. It crosses Kongmaru La at 5,260 m before descending to Shang Sumdo. The scenery is rugged and the culture rich.', array['Kongmaru La', 'Villages and monasteries', 'Hemis National Park']::text[], array['himalayan', 'pass', 'cultural', 'river', 'camping', 'high-altitude']::text[], 'Hemis National Park entry fee is collected en route', null, true),
  ('stok-kangri', 'Stok Kangri', 'Ladakh', 'Leh', 'Stok range', 'challenging'::public.trek_difficulty, 8, 6153, 40, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Stok', 'Kushok Bakula Rimpochee Airport, Leh', 'Jammu Tawi', 'A 6,153 m trekking peak above Leh, closed to climbers since 2020 to let the Stok glacier recover.', 'From Stok village the classic route followed Rumbak and Mankarmo to base camp, then a midnight push over scree and glacier to the summit. Local authorities closed the peak in 2020 to protect the glacier that feeds Stok village, and no reopening has been confirmed. Check with Leh authorities before planning; Markha Valley is a popular alternative.', array['6,000 m summit', 'Rumbak village', 'Panorama of Karakoram']::text[], array['himalayan', 'summit', 'high-altitude', 'glacier', 'camping']::text[], 'Confirm current permit and closure rules with Leh authorities', null, false),
  ('lamayuru-alchi', 'Lamayuru to Alchi', 'Ladakh', 'Leh', 'Zanskar range', 'moderate'::public.trek_difficulty, 5, 3700, 60, array['Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct']::text[], array['spring', 'summer', 'monsoon', 'autumn']::text[], 'Lamayuru', 'Kushok Bakula Rimpochee Airport, Leh', 'Jammu Tawi', 'A Sham valley monastery-to-monastery trek through moonscapes and village homestays.', 'The trail connects Lamayuru with Alchi via passes and village stays in the Sham region. Terrain is dry and dramatic, with lunar valleys and Buddhist gompas. It is an option for lower altitude trekking in Ladakh.', array['Moon-like valleys', 'Monasteries', 'Village homestays']::text[], array['himalayan', 'cultural', 'pass', 'river']::text[], null, null, false),
  ('rangdum-padum', 'Rangdum to Padum', 'Ladakh', 'Zanskar, Kargil', 'Zanskar range', 'moderate'::public.trek_difficulty, 5, 4400, 80, array['Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Rangdum', 'Kushok Bakula Rimpochee Airport, Leh', 'Jammu Tawi', 'A remote Zanskar crossing over Pensi La with glacier views.', 'The trek leaves Rangdum monastery and climbs through Parkachik toward Pensi La, with the Drang Drung glacier in sight. It then descends to Padum through Zanskar villages. Tracks are exposed, so go prepared.', array['Drang Drung glacier', 'Pensi La', 'Zanskar villages']::text[], array['himalayan', 'pass', 'glacier', 'cultural', 'camping']::text[], null, null, false),
  ('goechala', 'Goechala', 'Sikkim', 'West Sikkim', 'Kanchenjunga range', 'difficult'::public.trek_difficulty, 11, 4940, 90, array['Apr', 'May', 'Oct', 'Nov']::text[], array['spring', 'autumn']::text[], 'Yuksom', 'Pakyong Airport / Bagdogra Airport', 'New Jalpaiguri', 'A grand Kanchenjunga trek through rhododendron forests to the pass beneath the third highest peak.', 'From Yuksom the trail climbs through rhododendron forest to Dzongri and Thansing, then the pre-dawn push to Goecha La. The view of Kanchenjunga''s east face at sunrise is the highlight. Weather windows are best in spring and autumn.', array['Kanchenjunga sunrise', 'Samiti Lake', 'Rhododendron forests', 'Dzongri ridge']::text[], array['himalayan', 'northeast', 'pass', 'high-altitude', 'camping', 'forest']::text[], 'Permits obtained at Yuksom (Kanchenjunga National Park, Sikkim forest department)', null, true),
  ('dzongri', 'Dzongri', 'Sikkim', 'West Sikkim', 'Kanchenjunga range', 'moderate'::public.trek_difficulty, 6, 4170, 45, array['Mar', 'Apr', 'May', 'Oct', 'Nov']::text[], array['spring', 'autumn']::text[], 'Yuksom', 'Pakyong Airport / Bagdogra Airport', 'New Jalpaiguri', 'A shorter West Sikkim trek with close views of Pandim and Kanchenjunga.', 'The route covers forest to Sachen, Bakhim and Phedang before the Dzongri ridge. Sunrise from Dzongri Top lights Pandim, Kabru and Kanchenjunga. It is a good alternative when Goechala is too long.', array['Dzongri Top sunrise', 'Rhododendron bloom', 'Pandim view']::text[], array['himalayan', 'northeast', 'forest', 'camping', 'high-altitude']::text[], 'Permits obtained at Yuksom (Kanchenjunga National Park)', null, false),
  ('sandakphu-phalut', 'Sandakphu Phalut', 'West Bengal', 'Darjeeling', 'Singalila Ridge', 'moderate'::public.trek_difficulty, 6, 3636, 60, array['Mar', 'Apr', 'May', 'Oct', 'Nov']::text[], array['spring', 'autumn']::text[], 'Maneybhanjan', 'Bagdogra Airport', 'New Jalpaiguri', 'A ridge walk along the Nepal border with views of four of the world''s five highest peaks.', 'The route follows the Singalila ridge from Maneybhanjan past Tumling, Kalipokhri and Sandakphu to Phalut. On clear days Everest, Kanchenjunga, Lhotse and Makalu appear in one sweep. Trails are mostly gentle but long.', array['Everest-Kanchenjunga panorama', 'Singalila National Park', 'Rhododendron forests']::text[], array['himalayan', 'forest', 'summit', 'camping']::text[], 'Singalila National Park entry fee; hired guide is mandatory', null, true),
  ('green-lake', 'Green Lake Trek', 'Sikkim', 'North Sikkim', 'Kanchenjunga range', 'challenging'::public.trek_difficulty, 11, 5050, 100, array['Apr', 'May', 'Oct', 'Nov']::text[], array['spring', 'autumn']::text[], 'Lachen', 'Pakyong Airport / Bagdogra Airport', 'New Jalpaiguri', 'A remote glacial-lake expedition at the foot of Kanchenjunga''s northern face.', 'The route follows the Zemu glacier valley through high-altitude terrain beyond Lachen. The Green Lake lies amid moraines beneath Kanchenjunga. It is remote, cold and logistically complex.', array['Kanchenjunga north face', 'Zemu glacier', 'Remote alpine terrain']::text[], array['himalayan', 'northeast', 'glacier', 'lakes', 'high-altitude', 'camping']::text[], 'Protected-area permits arranged via registered Sikkim operators; confirm current rules', null, false),
  ('varsey-rhododendron', 'Varsey Rhododendron Trek', 'Sikkim', 'West Sikkim', 'Singalila Ridge', 'easy'::public.trek_difficulty, 3, 3100, 20, array['Mar', 'Apr', 'May']::text[], array['spring']::text[], 'Hilley', 'Bagdogra Airport', 'New Jalpaiguri', 'A gentle spring walk through a sanctuary of blooming rhododendrons.', 'The trail from Hilley follows the Singalila ridge through rhododendron groves in full bloom in April. Views of Kanchenjunga and the Singalila range appear on clear days. It is suited to beginners and families.', array['Rhododendron bloom', 'Ridge views', 'Easy gradients']::text[], array['himalayan', 'northeast', 'forest', 'beginner', 'family']::text[], null, null, false),
  ('dzukou-valley', 'Dzukou Valley', 'Nagaland', 'Kohima', 'Naga Hills', 'moderate'::public.trek_difficulty, 2, 2452, 18, array['Jun', 'Jul', 'Aug', 'Sep', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['summer', 'monsoon', 'autumn', 'winter', 'spring']::text[], 'Viswema', 'Dimapur Airport', 'Dimapur', 'A misty valley of wildflowers and rolling hills in the Naga Hills.', 'Starting at Viswema, the steep climb eases into a huge bowl of grass and flowers. Monsoon brings the Dzukou lily bloom. Weather is changeable, with fog and rain common.', array['Valley of lilies', 'Rolling green hills', 'Stone cabin camps']::text[], array['northeast', 'meadows', 'camping', 'monsoon']::text[], 'Inner Line Permit required for non-Nagaland Indians', null, false),
  ('nongriat-living-root-bridges', 'Nongriat Living Root Bridges', 'Meghalaya', 'East Khasi Hills', 'Khasi Hills', 'moderate'::public.trek_difficulty, 2, 1300, 12, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May']::text[], array['autumn', 'winter', 'spring']::text[], 'Tyrna', 'Shillong Airport / Guwahati Airport', 'Guwahati', 'A trek down thousands of steps to living root bridges in the Khasi forests.', 'The path from Tyrna descends through jungle to the double-decker living root bridge and Rainbow Falls. The bridges are grown by Khasi communities over decades from rubber fig roots. The return climb is long and stair-heavy.', array['Double-decker root bridge', 'Rainbow Falls', 'Khasi villages']::text[], array['northeast', 'waterfall', 'forest', 'cultural', 'river']::text[], null, null, false),
  ('phawngpui-blue-mountain', 'Phawngpui Blue Mountain', 'Mizoram', 'Lawngtlai', 'Mizo Hills', 'easy'::public.trek_difficulty, 2, 2157, 10, array['Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['autumn', 'winter', 'spring']::text[], 'Vawmbuk', 'Lengpui Airport, Aizawl', 'Silchar', 'Mizoram''s highest peak, a cloud-forest hike with orchids and rare birds.', 'The trail climbs from Vawmbuk to the plateau at the top, rich in orchids and rhododendrons. The summit gives wide views into Myanmar and Bangladesh on clear days. It is quiet, remote and gentle.', array['Mizoram''s highest peak', 'Orchids and birds', 'Border views']::text[], array['northeast', 'summit', 'forest', 'wildlife', 'beginner']::text[], 'Inner Line Permit required for visitors from outside Mizoram', null, false),
  ('mechuka', 'Mechuka Valley', 'Arunachal Pradesh', 'Shi Yomi', 'Eastern Himalaya', 'easy'::public.trek_difficulty, 4, 1800, 25, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr']::text[], array['autumn', 'winter', 'spring']::text[], 'Mechuka', 'Dibrugarh Airport', 'North Lakhimpur / Dibrugarh', 'A remote Siyom river valley walk past hanging bridges and monasteries.', 'The trails weave around Mechuka''s Siyom river, villages and the Samten Yongcha monastery. Prayer flags hang across pine-edged slopes. Roads and weather make logistics slow, so allow extra days.', array['Siyom river', 'Samten Yongcha monastery', 'Hanging bridges']::text[], array['northeast', 'cultural', 'river', 'forest']::text[], 'Inner Line Permit required for Indian visitors', null, false),
  ('harishchandragad', 'Harishchandragad', 'Maharashtra', 'Ahmednagar', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 2, 1424, 14, array['Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Pachnai', 'Pune Airport', 'Kalyan / Kasara', 'A rugged Sahyadri fort with the legendary Konkan Kada cliff and an ancient cave temple.', 'The fort perches on a large plateau with the Kedareshwar cave, Taramati peak and the 600 m Konkan Kada cliff. Multiple routes lead up, from gentle to challenging. Sunrise and mist at the cliff-edge are a trekking rite of passage in Maharashtra.', array['Konkan Kada cliff', 'Kedareshwar cave', 'Taramati peak']::text[], array['sahyadri', 'fort', 'camping', 'monsoon', 'waterfall']::text[], null, null, true),
  ('kalsubai', 'Kalsubai', 'Maharashtra', 'Ahmednagar', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 1646, 12, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Bari', 'Mumbai Airport / Nashik Airport', 'Igatpuri', 'The highest peak in Maharashtra, with iron ladders and sweeping valley views.', 'From Bari village the stone path rises to a series of iron ladders and the summit shrine. Monsoon turns the slopes bright green and lays mist in the valleys. It makes a popular day trek from Mumbai and Pune.', array['Highest peak of Maharashtra', 'Iron ladders', 'Summit shrine']::text[], array['sahyadri', 'summit', 'monsoon', 'weekend']::text[], null, null, false),
  ('rajgad', 'Rajgad', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 2, 1376, 14, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Gunjavane', 'Pune Airport', 'Pune', 'The ''king of forts'' and early capital of the Maratha empire.', 'The fort has three machis (terraces) and the formidable Sanjeevani machi. Routes include the Gunjavane trail and the Padmavati machi path. It takes more than a day to explore thoroughly.', array['Sanjeevani machi', 'Padmavati lake', 'Historic Maratha capital']::text[], array['sahyadri', 'fort', 'monsoon', 'camping', 'cultural']::text[], null, null, false),
  ('torna', 'Torna', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 1403, 10, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Velhe', 'Pune Airport', 'Pune', 'The first fort captured by Shivaji, with commanding views over the Sahyadri ridge.', 'The climb from Velhe passes Budhla machi and a succession of gates before the Zunjar machi. The summit reveals neighbouring forts like Rajgad and Raigad. It is a steady but steep ascent.', array['Shivaji''s first conquest', 'Zunjar machi', 'Panoramic views']::text[], array['sahyadri', 'fort', 'monsoon', 'cultural']::text[], null, null, false),
  ('lohagad', 'Lohagad', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'easy'::public.trek_difficulty, 1, 1033, 6, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Malavli', 'Pune Airport', 'Malavli', 'An easy fort walk with the Vinchu Kada scorpion-tail ridge.', 'The stone steps climb to a succession of four gates, then an open plateau with a Sufi shrine and old cisterns. The Vinchu Kada ridge juts out like a scorpion tail. Monsoon mist adds to the charm.', array['Vinchu Kada ridge', 'Four fort gates', 'Beginner-friendly']::text[], array['sahyadri', 'fort', 'monsoon', 'beginner', 'weekend']::text[], null, null, false),
  ('visapur', 'Visapur', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'easy'::public.trek_difficulty, 1, 1084, 5, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Malavli', 'Pune Airport', 'Malavli', 'A twin of Lohagad with rock-cut caves and monsoon waterfalls.', 'The trail follows steep stone steps, with waterfalls cascading down the fort''s slopes. Cisterns and rock-cut caves dot the plateau. Many combine it with Lohagad.', array['Waterfall slopes', 'Plateau ruins', 'Combines with Lohagad']::text[], array['sahyadri', 'fort', 'monsoon', 'waterfall', 'beginner']::text[], null, null, false),
  ('ratangad', 'Ratangad', 'Maharashtra', 'Ahmednagar', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 2, 1297, 9, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Ratanwadi', 'Mumbai Airport / Nashik Airport', 'Igatpuri', 'A fort famed for its Nedhe (needle-eye) pinnacle and Amruteshwar temple.', 'The route from Ratanwadi passes the Amruteshwar temple on the Pravara river, then a steep climb to the fort. The Nedhe rock formation has a natural hole in it. Views of Kalsubai range appear from the top.', array['Nedhe needle-eye', 'Amruteshwar temple', 'Kalsubai range views']::text[], array['sahyadri', 'fort', 'camping', 'monsoon']::text[], null, null, false),
  ('sandhan-valley', 'Sandhan Valley', 'Maharashtra', 'Ahmednagar', 'Sahyadri (Western Ghats)', 'difficult'::public.trek_difficulty, 2, 1000, 10, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar', 'Apr', 'May']::text[], array['autumn', 'winter', 'spring']::text[], 'Samrad', 'Mumbai Airport / Nashik Airport', 'Igatpuri', 'A deep sandstone canyon known as the ''Valley of Shadows''.', 'Trekkers descend through narrow rock passages into a dramatic canyon, with some rappelling and rope-assisted sections. It is best done in the dry season. Guides are strongly advised.', array['Slot canyon', 'Rappelling sections', 'Valley of Shadows']::text[], array['sahyadri', 'camping', 'river']::text[], null, null, false),
  ('andharban', 'Andharban', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 900, 7, array['Jun', 'Jul', 'Aug', 'Sep']::text[], array['monsoon']::text[], 'Pimpri (Tamhini)', 'Pune Airport', 'Pune', 'A dense monsoon jungle trek through the dark forest of Tamhini Ghat.', 'The trail drops into a thick forest whose canopy blocks most sunlight, with streams and waterfalls everywhere. The descent is slippery in rain. It is a popular day trek during the rainy season.', array['Canopy forest', 'Waterfalls', 'Streams']::text[], array['sahyadri', 'forest', 'monsoon', 'waterfall', 'weekend']::text[], null, null, false),
  ('kalavantin-durg', 'Kalavantin Durg', 'Maharashtra', 'Raigad', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 701, 5, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Thakurwadi', 'Mumbai Airport', 'Panvel', 'A steep rock-cut staircase on a sheer pinnacle next to Prabalgad.', 'The climb uses narrow steps carved into the cliff with a railing in places. The summit gives a bird''s-eye view of the Panvel plain. Care is needed in wet weather.', array['Rock-cut staircase', 'Prabalgad view', 'Cliff-edge views']::text[], array['sahyadri', 'fort', 'monsoon', 'camping']::text[], null, null, false),
  ('raigad', 'Raigad', 'Maharashtra', 'Raigad', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 1356, 6, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Pachad', 'Pune Airport', 'Mangaon', 'The capital fort of Shivaji, famous for its 1,737 steps and Maratha coronation site.', 'The steps lead up to a wide plateau with the royal court, bazaar ruins and Shivaji''s samadhi. A ropeway offers an alternative ascent. The fort is deeply historic.', array['Coronation site', '1,737 steps', 'Samadhi of Shivaji']::text[], array['sahyadri', 'fort', 'cultural', 'monsoon', 'family']::text[], null, null, false),
  ('sinhagad', 'Sinhagad', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'easy'::public.trek_difficulty, 1, 1312, 4, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Sinhagad Base', 'Pune Airport', 'Pune', 'A quick Pune-area fort hike with a famous battle history.', 'The climb takes about two hours via a steep path through forest and rocky patches. The fort has a Tanaji memorial, gates and sweeping views of the Khadakwasla lake. Mist makes it special in monsoon.', array['Tanaji memorial', 'Khadakwasla views', 'Fort gates']::text[], array['sahyadri', 'fort', 'beginner', 'weekend', 'cultural']::text[], null, null, false),
  ('alang-madan-kulang', 'Alang Madan Kulang', 'Maharashtra', 'Nashik', 'Sahyadri (Western Ghats)', 'challenging'::public.trek_difficulty, 2, 1479, 12, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Ambewadi', 'Mumbai Airport / Nashik Airport', 'Igatpuri', 'The toughest trio of forts in the Sahyadri, with exposed rock climbs.', 'The trail covers the fort trio with vertical climbs, ladders and cliff-hugging paths. Some patches need rope and technical skills. Only experienced trekkers with guides should attempt it.', array['Three forts in one trek', 'Exposed rock climbs', 'Remote jungle']::text[], array['sahyadri', 'fort', 'camping']::text[], null, null, false),
  ('peb-fort', 'Peb Fort (Vikatgad)', 'Maharashtra', 'Raigad', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 700, 6, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Neral', 'Mumbai Airport', 'Neral', 'A Matheran-side fort with a rock-cut cave and a precarious pinnacle.', 'The trail climbs from Neral to a pass and then the ridge with the Vikatgad pinnacle called Nakhind. The cave on the plateau serves as a shelter. The climb on the final rock patch is exposed.', array['Nakhind pinnacle', 'Rock cave', 'Neral approach']::text[], array['sahyadri', 'fort', 'monsoon', 'camping']::text[], null, null, false),
  ('bhimashankar', 'Bhimashankar', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 2, 1034, 12, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Khandas', 'Pune Airport', 'Karjat', 'A jungle trek to the Jyotirlinga temple through the Shidi or Ganpati ghat.', 'The path climbs through the Bhimashankar Wildlife Sanctuary, home to the Indian giant squirrel. The Ganpati Ghat route is gentler than Shidi Ghat. The temple is one of the twelve Jyotirlingas.', array['Jyotirlinga temple', 'Wildlife sanctuary', 'Giant squirrel habitat']::text[], array['sahyadri', 'forest', 'cultural', 'wildlife', 'monsoon']::text[], null, null, false),
  ('harihar-fort', 'Harihar Fort', 'Maharashtra', 'Nashik', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 1120, 5, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Nirgudpada', 'Nashik Airport', 'Nashik Road', 'A fort with a nearly vertical rock-cut stair climbing at 80 degrees.', 'A stone staircase is carved into the rock face in a spectacular, exposed ascent. The top has small caves, a temple and an old gateway. The climb is short but dramatic.', array['80-degree rock staircase', 'Cliff-edge ascent', 'Hilltop views']::text[], array['sahyadri', 'fort', 'monsoon', 'camping']::text[], null, null, false),
  ('korigad', 'Korigad', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'easy'::public.trek_difficulty, 1, 923, 5, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Peth Shahapur', 'Pune Airport', 'Lonavala', 'A well-preserved fort close to Lonavala with a wide fortification.', 'The short trail climbs to a plateau ringed by walls and gates, with a lake and temple. Cannons rest on the ramparts. Views extend over Aamby Valley.', array['Preserved ramparts', 'Lake and temple', 'Beginner-friendly']::text[], array['sahyadri', 'fort', 'beginner', 'weekend']::text[], null, null, false),
  ('tikona', 'Tikona', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'easy'::public.trek_difficulty, 1, 1070, 5, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Tikona Peth', 'Pune Airport', 'Lonavala', 'A pyramid-shaped hill fort above Pawna Lake.', 'The route climbs steps carved into rock to a narrow gateway and a small cave. The pointed shape of the fort makes it easy to recognise. Pawna Lake views reward the climb.', array['Pyramid-shaped fort', 'Pawna Lake views', 'Rock steps']::text[], array['sahyadri', 'fort', 'beginner', 'weekend']::text[], null, null, false),
  ('mahuli-fort', 'Mahuli Fort', 'Maharashtra', 'Thane', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 2, 860, 8, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Asangaon', 'Mumbai Airport', 'Asangaon', 'A three-peak fort near Mumbai with rock walls and waterfalls.', 'The fort area includes Mahuligad, Bhandargad and Palasgad, with the Navra-Navri pinnacles. The climb has some steep scrambles. It is popular for monsoon and night treks.', array['Navra-Navri pinnacles', 'Three summits', 'Waterfalls']::text[], array['sahyadri', 'fort', 'monsoon', 'camping']::text[], null, null, false),
  ('naneghat', 'Naneghat', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'moderate'::public.trek_difficulty, 1, 850, 8, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Vaiyal', 'Pune Airport', 'Kalyan', 'An ancient trade pass with a Satavahana-era cave and a thumb-shaped pinnacle.', 'The old pass links the Konkan with the Deccan, with a large cave of inscriptions. The famous Jeevdhan Fort stands beside it with its tall pinnacle. Monsoon winds can be fierce at the pass.', array['Ancient trade route', 'Satavahana inscriptions', 'Jeevdhan pinnacle']::text[], array['sahyadri', 'cultural', 'monsoon', 'weekend']::text[], null, null, false),
  ('dhak-bahiri', 'Dhak Bahiri', 'Maharashtra', 'Pune', 'Sahyadri (Western Ghats)', 'difficult'::public.trek_difficulty, 1, 820, 10, array['Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['monsoon', 'autumn', 'winter']::text[], 'Jambhivali', 'Pune Airport', 'Karjat', 'A dramatic cave trek with a steep rock face and a waterfall inside the cave.', 'The trail leads through dense forest to a large cave beneath a cliff, with a waterfall during the rains. A final narrow climb requires care. Guides are advised.', array['Large cave with waterfall', 'Dense forest trail', 'Exposed climb']::text[], array['sahyadri', 'monsoon', 'waterfall', 'camping']::text[], null, null, false),
  ('kudremukh', 'Kudremukh', 'Karnataka', 'Chikmagalur', 'Western Ghats', 'moderate'::public.trek_difficulty, 2, 1894, 20, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Mullodi', 'Mangaluru Airport', 'Mangaluru', 'A grassland-and-shola ridge trek whose horse-face profile gives the peak its name.', 'The trail climbs through open rolling grassland dotted with shola forest and streams. The summit looks across to the Arabian Sea on clear days. Monsoon is lush but leech-prone.', array['Rolling grassland ridge', 'Shola forests', 'Horse-face peak']::text[], array['western-ghats', 'forest', 'wildlife', 'camping', 'weekend']::text[], 'Forest department entry permit (online booking)', null, true),
  ('kumara-parvatha', 'Kumara Parvatha', 'Karnataka', 'Kodagu', 'Western Ghats', 'difficult'::public.trek_difficulty, 2, 1712, 26, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Kukke Subramanya', 'Mangaluru Airport', 'Subrahmanya Road', 'One of Karnataka''s toughest treks, with a rocky final ascent and grassy ridges.', 'The trek begins at Kukke Subramanya temple, goes through Bidirukodi forest and Girigadde base, and climbs steeply to Pushpagiri''s neighbouring peak. The terrain is steep and rocky. Views of the Western Ghats unfold at the summit.', array['Steep rocky climb', 'Pushpagiri Wildlife Sanctuary', 'Sunset camp at Girigadde']::text[], array['western-ghats', 'forest', 'summit', 'camping']::text[], 'Forest permit for Pushpagiri Wildlife Sanctuary', null, false),
  ('tadiandamol', 'Tadiandamol', 'Karnataka', 'Kodagu', 'Western Ghats', 'moderate'::public.trek_difficulty, 1, 1748, 12, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Kakkabe', 'Mangaluru Airport', 'Mysuru', 'Coorg''s highest peak, with sweeping grassland views.', 'The walk starts at Kakkabe, passes the Nalknad Palace, and climbs grassy slopes to the summit. Mist often wraps the ridge. The trail is clear and good for first-time Ghat trekkers.', array['Highest peak of Kodagu', 'Open grassland', 'Nalknad palace']::text[], array['western-ghats', 'summit', 'forest', 'weekend']::text[], null, null, false),
  ('mullayanagiri', 'Mullayanagiri', 'Karnataka', 'Chikmagalur', 'Baba Budangiri range', 'easy'::public.trek_difficulty, 1, 1930, 6, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Sarpadhari', 'Bengaluru Airport', 'Chikmagalur / Kadur', 'The highest peak in Karnataka, a short climb with a temple on top.', 'About 500 steps lead to a small temple on the summit, with views over coffee estates and the Baba Budan range. Sunrise and mist are the highlights. It is easy and family friendly.', array['Highest peak of Karnataka', 'Coffee-estate views', 'Sunrise']::text[], array['western-ghats', 'summit', 'family', 'beginner']::text[], null, null, false),
  ('netravati-peak', 'Netravati Peak', 'Karnataka', 'Dakshina Kannada', 'Western Ghats', 'moderate'::public.trek_difficulty, 1, 1520, 12, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Kurinjal', 'Mangaluru Airport', 'Mangaluru', 'A grassy peak trek above the source of the Netravati river.', 'The trail runs through grassland and rocky ridge to the peak. Views reach the Arabian Sea and Kudremukh range. Forest permission may be needed.', array['Source of Netravati river', 'Open grassland', 'Sea views']::text[], array['western-ghats', 'summit', 'forest', 'camping']::text[], null, null, false),
  ('skandagiri', 'Skandagiri', 'Karnataka', 'Chikkaballapur', 'Nandi Hills range', 'easy'::public.trek_difficulty, 1, 1350, 8, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Papagni Mutt', 'Bengaluru Airport', 'Chikkaballapur', 'A famous pre-dawn trek above a sea of clouds near Bengaluru.', 'Hikers climb in the early hours to catch the sunrise above cloud-filled valleys. The path has rocky stairs and a final steep stretch. Camping at the top is regulated, so check current rules.', array['Sunrise above clouds', 'Fort ruins', 'Easy drive from Bengaluru']::text[], array['western-ghats', 'weekend', 'beginner']::text[], null, null, false),
  ('brahmagiri', 'Brahmagiri', 'Karnataka', 'Kodagu', 'Western Ghats', 'moderate'::public.trek_difficulty, 1, 1607, 10, array['Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Irpu', 'Mysuru Airport', 'Mysuru', 'A Kodagu-Kerala border ridge trek through Brahmagiri Wildlife Sanctuary.', 'The trail climbs through shola forest and grasslands toward the Kerala border. Wildlife such as elephants and gaur occasionally appear. Entry is regulated by the forest department.', array['Wildlife sanctuary', 'Grassy ridge', 'Border views']::text[], array['western-ghats', 'forest', 'wildlife']::text[], null, null, false),
  ('kodachadri', 'Kodachadri', 'Karnataka', 'Shivamogga', 'Western Ghats', 'moderate'::public.trek_difficulty, 2, 1343, 20, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Kollur', 'Mangaluru Airport', 'Kundapura', 'A beautiful trek to a mountain shrine above misty forests near Mookambika.', 'The trek winds through forest and rocky outcrops to a hilltop with a shrine and sunset-view spot. Jeep rides are possible. The area is a biodiversity hotspot.', array['Hilltop shrine', 'Sunset viewpoint', 'Hidden Falls']::text[], array['western-ghats', 'forest', 'summit']::text[], null, null, false),
  ('chembra-peak', 'Chembra Peak', 'Kerala', 'Wayanad', 'Western Ghats', 'moderate'::public.trek_difficulty, 1, 2100, 8, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Meppadi', 'Kozhikode Airport', 'Kozhikode', 'Wayanad''s highest peak, with a heart-shaped lake on the way up.', 'The trail climbs through tea estates and grassy slopes to the Heart Lake and the top. A forest permit is required. The area was affected by landslides in 2024, so confirm access.', array['Heart-shaped lake', 'Tea estate approach', 'Wayanad''s top']::text[], array['western-ghats', 'summit', 'lakes', 'forest']::text[], 'Forest department permit via DTPC Wayanad; confirm current access', null, false),
  ('meesapulimala', 'Meesapulimala', 'Kerala', 'Idukki', 'Western Ghats', 'difficult'::public.trek_difficulty, 3, 2640, 20, array['Dec', 'Jan', 'Feb']::text[], array['winter']::text[], 'Rhodo Valley', 'Cochin Airport', 'Aluva / Ernakulam', 'One of Kerala''s highest trek peaks with rhododendron valleys and high grassland.', 'The route begins near Munnar and climbs through grassland, rhododendron forest and rocky ridges to the summit. Book through the forest department. Cold nights and wind are typical.', array['Rhododendron valley', 'High grassland', 'Munnar views']::text[], array['western-ghats', 'summit', 'camping', 'forest']::text[], 'Kerala Forest Department booking required', null, false),
  ('agasthyarkoodam', 'Agasthyarkoodam', 'Kerala', 'Thiruvananthapuram', 'Western Ghats', 'difficult'::public.trek_difficulty, 3, 1868, 26, array['Jan', 'Feb', 'Mar']::text[], array['winter', 'spring']::text[], 'Bonaccord', 'Thiruvananthapuram Airport', 'Thiruvananthapuram', 'A rain-forest trek to the Agastya peak, open for only a short season.', 'The trail climbs from Bonaccord through tropical forest and grasslands to the summit. A pilgrimage site, it requires online booking from the Kerala Forest Department. Trekking is open only during January to March.', array['Biosphere reserve', 'Pilgrimage peak', 'Medicinal forest']::text[], array['western-ghats', 'forest', 'summit', 'wildlife']::text[], 'Kerala Forest Department online booking; open only Jan–Mar', null, false),
  ('kolukkumalai', 'Kolukkumalai', 'Tamil Nadu', 'Theni', 'Western Ghats', 'easy'::public.trek_difficulty, 1, 2160, 10, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['autumn', 'winter', 'spring']::text[], 'Suryanelli', 'Madurai Airport', 'Theni / Bodinayakanur', 'One of the highest tea estates, with sunrise over a sea of clouds.', 'The trail climbs from Suryanelli through tea plantations near the Tamil Nadu border. Jeep rides are common. The sunrise views are the main attraction.', array['Highest-altitude tea estate', 'Sunrise above clouds', 'Easy walk']::text[], array['western-ghats', 'weekend', 'beginner']::text[], null, null, false),
  ('kurangani-top-station', 'Kurangani to Top Station', 'Tamil Nadu', 'Theni', 'Western Ghats', 'moderate'::public.trek_difficulty, 2, 1880, 12, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['autumn', 'winter', 'spring']::text[], 'Kurangani', 'Madurai Airport', 'Bodinayakanur', 'A hill trek linking Kurangani with the Top Station viewpoint.', 'The route climbs from Kurangani village through forest and tea estates toward the Top Station ridge. Views stretch across the Kerala-Tamil Nadu border. The path is steep in places.', array['Forest and tea trail', 'Top Station viewpoint', 'Border ridge']::text[], array['western-ghats', 'forest', 'camping']::text[], null, null, false),
  ('vellingiri', 'Vellingiri Hills', 'Tamil Nadu', 'Coimbatore', 'Nilgiri hills', 'difficult'::public.trek_difficulty, 2, 1778, 12, array['Feb', 'Mar', 'Apr', 'May']::text[], array['winter', 'spring']::text[], 'Poondi', 'Coimbatore Airport', 'Coimbatore', 'The ''Himalayas of the South'' – seven hills with a Shiva temple at the top.', 'Pilgrims climb seven hills for the Vellingiri Andavar temple. Terrain is steep and rocky, with a final cold stretch. The trek is typically open only in the dry months.', array['Seven-hill climb', 'Hilltop temple', 'Cold windy summit']::text[], array['western-ghats', 'cultural', 'summit', 'forest']::text[], 'Temple/forest entry rules apply; open Feb–May', null, false),
  ('mukurthi-peak', 'Mukurthi Peak', 'Tamil Nadu', 'Nilgiris', 'Nilgiri hills', 'moderate'::public.trek_difficulty, 2, 2554, 16, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Mukurthi National Park', 'Coimbatore Airport', 'Mettupalayam', 'The Nilgiris'' high peak inside Mukurthi National Park.', 'The trail passes Nilgiri tahr habitat on open grassland. Weather is cold and windy. Entry requires approvals from the forest department.', array['Nilgiri tahr habitat', 'Open shola grassland', 'Windy summit']::text[], array['western-ghats', 'wildlife', 'summit', 'forest']::text[], 'Tamil Nadu Forest Department permission required', null, false),
  ('banasura-hill', 'Banasura Hill', 'Kerala', 'Wayanad', 'Western Ghats', 'easy'::public.trek_difficulty, 1, 2073, 6, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Padinjarathara', 'Kozhikode Airport', 'Kozhikode', 'A grassy Wayanad hill beside India''s largest earthen dam.', 'The trail climbs from Banasura Sagar to the summit with views over the reservoir and rolling hills. It is short and suited to families. Check local access conditions after monsoon.', array['Banasura Sagar views', 'Grassy hills', 'Family friendly']::text[], array['western-ghats', 'family', 'beginner', 'weekend']::text[], null, null, false),
  ('dudhsagar', 'Dudhsagar Falls', 'Goa', 'South Goa', 'Western Ghats', 'easy'::public.trek_difficulty, 1, 310, 11, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Kulem', 'Dabolim Airport', 'Kulem', 'A walk to one of India''s tallest tiered waterfalls on the Goa-Karnataka border.', 'The trail leads through forest to the four-tier falls. Access rules, including the railway-track route, have changed, so confirm current options. Monsoon brings the strongest flow.', array['Four-tier waterfall', 'Forest trail', 'Rail viaduct']::text[], array['western-ghats', 'waterfall', 'forest', 'monsoon', 'family']::text[], 'Forest department entry (Bhagwan Mahavir Wildlife Sanctuary); confirm current rules', null, false),
  ('mount-abu-guru-shikhar', 'Guru Shikhar', 'Rajasthan', 'Sirohi', 'Aravalli range', 'easy'::public.trek_difficulty, 1, 1722, 8, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['autumn', 'winter', 'spring']::text[], 'Mount Abu', 'Udaipur Airport', 'Abu Road', 'A gentle climb to the highest point in the Aravallis.', 'A short stair path leads to the Dattatreya temple at the peak. Views stretch across Mount Abu''s forested plateau. Hill sights such as Nakki Lake and Dilwara Temples add variety.', array['Highest point of Aravallis', 'Hilltop temple', 'Cool hill-station climate']::text[], array['family', 'cultural', 'beginner']::text[], null, null, false),
  ('pachmarhi-dhupgarh', 'Dhupgarh', 'Madhya Pradesh', 'Narmadapuram', 'Satpura range', 'easy'::public.trek_difficulty, 1, 1352, 6, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['autumn', 'winter', 'spring']::text[], 'Pachmarhi', 'Bhopal Airport', 'Pipariya', 'Madhya Pradesh''s highest point in the Satpura hills with sunset views.', 'The path leads to a flat top where sunsets are famed across the Satpura valleys. Pachmarhi''s caves, falls and forests offer many side hikes. Best from monsoon end through winter.', array['Highest point of MP', 'Sunset views', 'Satpura forests']::text[], array['forest', 'family', 'beginner', 'wildlife']::text[], null, null, false),
  ('girnar', 'Girnar Hill', 'Gujarat', 'Junagadh', 'Girnar hills', 'moderate'::public.trek_difficulty, 1, 1117, 14, array['Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Junagadh', 'Rajkot Airport', 'Junagadh', 'A pilgrimage staircase of nearly 10,000 steps to Jain and Hindu shrines.', 'Pilgrims climb up through temple complexes of Jain, Hindu and Buddhist heritage. The steps are long, and most hike early to avoid heat. The higher peaks overlook Gir forest.', array['9,999 steps', 'Jain and Hindu temples', 'Gir forest views']::text[], array['cultural', 'summit', 'family']::text[], null, null, false),
  ('deomali', 'Deomali', 'Odisha', 'Koraput', 'Eastern Ghats', 'moderate'::public.trek_difficulty, 2, 1672, 10, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb']::text[], array['autumn', 'winter']::text[], 'Deomali village', 'Visakhapatnam Airport', 'Koraput', 'The highest peak in Odisha, set in the Eastern Ghats.', 'The trek crosses tribal villages and open hills to the summit. Winter weather is cool and clear. Local guides help with routes.', array['Highest peak of Odisha', 'Tribal villages', 'Eastern Ghats views']::text[], array['forest', 'summit', 'cultural', 'camping']::text[], null, null, false),
  ('parasnath-hill', 'Parasnath Hill', 'Jharkhand', 'Giridih', 'Parasnath hills', 'moderate'::public.trek_difficulty, 1, 1350, 27, array['Oct', 'Nov', 'Dec', 'Jan', 'Feb', 'Mar']::text[], array['autumn', 'winter', 'spring']::text[], 'Madhuban', 'Ranchi Airport', 'Parasnath / Giridih', 'A pilgrimage circuit of Jain shrines on Jharkhand''s highest hill.', 'Pilgrims walk a loop of about 27 km connecting numerous shrines along forested ridges. Many hike overnight for sunrise. It is a long but not technical walk.', array['Jain pilgrim circuit', 'Forested ridges', 'Sunrise views']::text[], array['cultural', 'forest', 'summit']::text[], null, null, false)
